create or replace function public.log_order_notification_event() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin if old.status is distinct from new.status then insert into public.customer_notification_events(order_id,event_type,channel,recipient,status) values(new.id,'order_status_'||new.status,'email',new.email,'queued'); end if; return new; end; $$;
drop trigger if exists order_notification_event_trigger on public.orders; create trigger order_notification_event_trigger after update of status on public.orders for each row execute function public.log_order_notification_event();
